@startuml

class Employee {
  + idNumber : string
  + name : string
  + address : string
}

class AssemblyService {
  + kmsAtTime : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class PartOrAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + idNumber : string
  + name : string
  + address : string
  + phone : string
}

Car "1" -- "*" AssemblyService : undergoes
AssemblyService "*" -- "1" Employee : responsibleFor
AssemblyService "*" -- "*" PartOrAccessory : uses
PartOrAccessory "*" -- "*" Car : fitsIn
Car "*" -- "1" Owner : ownedBy

@enduml

